def get_dataset(id, session):
    """Get a Dataset"""
    dataset = session.query(Dataset).get(id)
    if not dataset:
        raise NotFound(
            "Dataset not found",
            detail=f"The Dataset with id: `{id}` was not found",
        )
    return dataset_schema.dump(dataset)
